export default function prepare({ body }) {
  const event = JSON.parse(body.event);
  if (
    typeof event.text !== "string" ||
    event.text.length === 0 ||
    typeof event.response_url !== "string"
  )
    throw Error("Slack command text and response URL are required");
  return { name: event.text, description: event.text, responseUrl: event.response_url };
}

